static Texture2D ReadTexture(string path){var imp=(TextureImporter)AssetImporter.GetAtPath(path);imp.isReadable=true;imp.textureCompression=TextureImporterCompression.Uncompressed;imp.SaveAndReimport();return AssetDatabase.LoadAssetAtPath<Texture2D>(path);}
static void Pack(){var old=ReadTexture(D+"/Before Grand Yard Atlas.png");var added=ReadTexture(D+"/Grand Yard Paving and Helipad Source.png");var tex=new Texture2D(2048,1024,TextureFormat.RGBA32,false);var pixels=new Color[2048*1024];for(int tile=0;tile<8;tile++)for(int y=0;y<512;y++)for(int x=0;x<512;x++){float u=(x+.5f)/512,v=(y+.5f)/512;Color color=Color.white;if(tile<4)color=old.GetPixelBilinear((tile%2+u)/2,(1-tile/2+v)/2);else if(tile<6)color=added.GetPixelBilinear((tile-4+u)/2,v);else color=tile==6?new Color(.8f,.64f,.25f):Color.white;pixels[(tile<4?512+y:y)*2048+(tile%4)*512+x]=color;}tex.SetPixels(pixels);tex.Apply();File.WriteAllBytes(D+"/Shared Yacht Yard Atlas.png",tex.EncodeToPNG());UnityEngine.Object.DestroyImmediate(tex);AssetDatabase.ImportAsset(D+"/Shared Yacht Yard Atlas.png",ImportAssetOptions.ForceUpdate);var imp2=(TextureImporter)AssetImporter.GetAtPath(D+"/Shared Yacht Yard Atlas.png");imp2.mipmapEnabled=true;imp2.streamingMipmaps=true;imp2.npotScale=TextureImporterNPOTScale.None;imp2.isReadable=false;imp2.anisoLevel=4;foreach(string platform in new[]{"Android","iPhone"})imp2.SetPlatformTextureSettings(new TextureImporterPlatformSettings{name=platform,overridden=true,maxTextureSize=2048,format=TextureImporterFormat.ASTC_6x6,compressionQuality=90});imp2.SaveAndReimport();}
